theorem restriction_idempotent {V : Type u} {R : V -> V -> Prop}
    {S : V -> Prop} {a b : V} :
    Restrict (Restrict R S) S a b ↔ Restrict R S a b

theorem restriction_nested {V : Type u} {R : V -> V -> Prop}
    {S T : V -> Prop} (hTS : forall a, T a -> S a) {a b : V} :
    Restrict (Restrict R S) T a b ↔ Restrict R T a b

theorem nested_contraction_paths {V : Type u} {R : V → V → Prop}
    {K L : V → Prop} (hKL : ∀ a, K a → L a) {a b : V} (ha : K a) (hb : K b) :
    Reach (Contract (Contract R L) K) a b ↔ Reach (Contract R K) a b

theorem retained_path_iff {V : Type u} {R : V → V → Prop} {K : V → Prop}
    {a b : V} (ha : K a) (hb : K b) :
    Reach (Contract R K) a b ↔ Reach R a b

theorem path_projects_strict_of_distinct_owners {Genome : Type u}
    {R : Genome -> Genome -> Prop} {E : SpeciesBridge.Graph}
    (owner : Genome -> Nat)
    (edgeSound : forall g h, R g h -> SameOrDescendant E (owner g) (owner h))
    {g h : Genome} (path : Reach R g h) (different : owner g ≠ owner h) :
    SpeciesBridge.Descendant E (owner g) (owner h)
